local a=require"system.filesystem"local b=require"control"local function c(d)return string.match(d,'^()[%s%z]*$')and''or string.match(d,'^[%s%z]*(.*[^%s%z])')end;local e={status={not_installed=1,config_files=2,half_installed=3,unpacked=4,half_configured=5,triggers_awaited=6,triggers_pending=7,installed=8}}e.admindir="/var/lib/dpkg"if not a.isDir(e.admindir)then a.mkdir(e.admindir)end;function e.readDatabase()local f=io.open(a.combine(e.admindir,"status"),"r")if f==nil then error("Couldn't find status file")end;local g={{}}local h=nil;local d=1;for i in f:lines()do if i==""then d=d+1;g[d]={}h=nil else if string.sub(i,1,1)==" "and h~=nil then if h=="Description"then if type(g[d][h])=="string"then g[d][h]={Short=g[d][h],Long=""}end;g[d][h].Long=g[d][h].Long..(string.sub(i,2)=="."and"\n\n"or string.sub(i,2))else g[d][h]=g[d][h]..(string.sub(i,2)=="."and"\n\n"or string.sub(i,2))end else h=string.sub(i,1,(string.find(i,":")or 0)-1)g[d][h]=c(string.sub(i,(string.find(i,":")or-1)+1))end end end;f:close()local j={}for k,l in pairs(g)do if l.Package then j[l.Package]=l end end;return j end;function e.writeDatabase(m)a.copy(a.combine(e.admindir,"status"),a.combine(e.admindir,"status-old"))local f=a.open(a.combine(e.admindir,"status"),"w")if f==nil then error("Couldn't find status file")end;local function n(l)if type(l)=="table"then return(l.Short or"").."\n "..string.gsub(l.Long or"","\n\n","\n .\n")else return l end end;for k,l in pairs(m)do if not(string.match(l.Status,"(%S+) %S+ %S+")=="unknown"and string.match(l.Status,"%S+ %S+ (%S+)")=="not-installed")then f.writeLine("Package: "..k)for o,p in pairs(l)do if o~="Package"and o~="Description"then f.writeLine(o..": "..n(p))end end;if l.Description then f.writeLine("Description: "..n(l.Description))end;f.writeLine("")end end;f.close()end;function e.findPackage(q,r)r=r or e.readDatabase()for k,l in pairs(r)do if q==k then return l,r end end;return nil,r end;function e.readFileLists()local g={duplicates={}}local s=0;for t,l in i